use std::path::PathBuf;

use eframe::egui;

fn main() -> eframe::Result {
    let args: Vec<String> = std::env::args().collect();
    let screenshot: Option<PathBuf> = args
        .iter()
        .position(|a| a == "--screenshot")
        .and_then(|i| args.get(i + 1))
        .map(PathBuf::from);

    let mut viewport = egui::ViewportBuilder::default()
        .with_title("System Toolbox")
        .with_app_id("system_toolbox")
        .with_inner_size([1200.0, 780.0])
        .with_min_inner_size([920.0, 600.0])
        .with_icon(app_icon());

    // macOS: blend the title bar into the window for a modern look (traffic lights stay).
    #[cfg(target_os = "macos")]
    {
        viewport = viewport
            .with_fullsize_content_view(true)
            .with_title_shown(false)
            .with_titlebar_shown(false);
    }

    if screenshot.is_some() {
        // Never steal focus from the person while a check takes a picture.
        viewport = viewport.with_active(false);
        #[cfg(target_os = "windows")]
        {
            viewport = viewport.with_window_level(egui::WindowLevel::AlwaysOnBottom);
        }
    }

    #[allow(unused_mut)]
    let mut options = eframe::NativeOptions {
        viewport,
        persist_window: screenshot.is_none(),
        ..Default::default()
    };

    #[cfg(target_os = "macos")]
    if screenshot.is_some() {
        options.event_loop_builder = Some(Box::new(|builder| {
            use winit::platform::macos::EventLoopBuilderExtMacOS;
            builder.with_activate_ignoring_other_apps(false);
        }));
    }

    eframe::run_native(
        "System Toolbox",
        options,
        Box::new(move |cc| Ok(Box::new(app::ToolboxApp::new(cc, screenshot)))),
    )
}

/// A small generated app icon: a rounded square with an indigo-to-violet gradient and a white bolt-like mark.
fn app_icon() -> egui::IconData {
    let size = 64usize;
    let mut rgba = vec![0u8; size * size * 4];
    let r = 14.0f32;
    for y in 0..size {
        for x in 0..size {
            let fx = x as f32 + 0.5;
            let fy = y as f32 + 0.5;
            // rounded-rect mask
            let cx = fx.clamp(r, size as f32 - r);
            let cy = fy.clamp(r, size as f32 - r);
            let d = ((fx - cx).powi(2) + (fy - cy).powi(2)).sqrt();
            let alpha = (r - d + 0.5).clamp(0.0, 1.0);
            let t = (fx + fy) / (2.0 * size as f32);
            let (r0, g0, b0) = (99.0, 102.0, 241.0);
            let (r1, g1, b1) = (168.0, 85.0, 247.0);
            let mut col = [
                r0 + (r1 - r0) * t,
                g0 + (g1 - g0) * t,
                b0 + (b1 - b0) * t,
            ];
            // white mark: three stacked bars (a stylised "toolbox" grid)
            let in_bar = |x0: f32, y0: f32, w: f32, h: f32| fx >= x0 && fx <= x0 + w && fy >= y0 && fy <= y0 + h;
            if in_bar(16.0, 18.0, 32.0, 6.0) || in_bar(16.0, 29.0, 22.0, 6.0) || in_bar(16.0, 40.0, 28.0, 6.0) {
                col = [255.0, 255.0, 255.0];
            }
            let i = (y * size + x) * 4;
            rgba[i] = col[0] as u8;
            rgba[i + 1] = col[1] as u8;
            rgba[i + 2] = col[2] as u8;
            rgba[i + 3] = (alpha * 255.0) as u8;
        }
    }
    egui::IconData {
        rgba,
        width: size as u32,
        height: size as u32,
    }
}

