/// iOS-style toggle switch.
pub fn toggle(ui: &mut Ui, p: &Palette, on: &mut bool) -> Response {
    let size = vec2(40.0, 22.0);
    let (rect, mut resp) = ui.allocate_exact_size(size, Sense::click());
    if resp.clicked() {
        *on = !*on;
        resp.mark_changed();
    }
    let t = ui.ctx().animate_bool(resp.id, *on);
    let bg = mix(p.track, p.accent, t);
    let painter = ui.painter();
    painter.rect_filled(rect, 11, bg);
    let x = egui::lerp((rect.left() + 11.0)..=(rect.right() - 11.0), t);
    painter.circle_filled(pos2(x, rect.center().y), 8.0, Color32::WHITE);
    resp.on_hover_cursor(egui::CursorIcon::PointingHand)
}

/// Segmented control: returns the newly chosen index when it changes.
pub fn segmented(ui: &mut Ui, p: &Palette, options: &[&str], selected: usize) -> Option<usize> {
    let mut out = None;
    Frame::new()
        .fill(p.track)
        .corner_radius(CornerRadius::same(10))
        .inner_margin(Margin::same(3))
        .show(ui, |ui| {
            ui.spacing_mut().item_spacing.x = 2.0;
            ui.horizontal(|ui| {
                for (i, o) in options.iter().enumerate() {
                    let sel = i == selected;
                    let btn = egui::Button::new(
                        RichText::new(*o)
                            .color(if sel { p.text } else { p.muted })
                            .font(FontId::new(13.0, if sel { bold() } else { egui::FontFamily::Proportional })),
                    )
                    .fill(if sel { p.card } else { Color32::TRANSPARENT })
                    .stroke(if sel { Stroke::new(1.0, p.border) } else { Stroke::NONE })
                    .corner_radius(8)
                    .min_size(vec2(64.0, 28.0));
                    if ui.add(btn).clicked() && !sel {
                        out = Some(i);
                    }
                }
            });
        });
    out
}

